trim.if:
SELECT #{VALID_STATUS_01} validStatus, T1.WORKFLOW_ID workflowId, T1.WORKFLOW_STATUS workflowStatus, T1.TOTLE_TRADE_ID busiCode, T2.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, T3.FINPROD_ID finprodId, T3.FINPROD_NAME finprodName, T1.PS ps,
CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS prinAmt, T4.PRIN_AMT winlotteryAmt, T2.PURCH_DATE purchDate,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS tradeDate, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS settleDate, T2.PURCH_MODLE purchModle, T2.PURCH_TYPE purchType, T1.TRADE_MARKET tradeMarket, T1.CCY ccy, T1.REMARK remark FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID
WHERE T1.TRADE_STATUS = #{VALID_STATUS_01}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/
AND T1.PS IN
#{item}
AND ( pp.PORTFOLIO_ID IN
null) or pp.PORTFOLIO_ID in (
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
null) or pp.PARENT_PORTFOLIO_ID in (
#{item}
)
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND T2.ENTRUST_ID like CONCAT('%', CONCAT(#{entrustId}, '%'))
AND T1.FINPROD_ID like CONCAT('%', CONCAT(#{finprodId}, '%'))
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS = #{ps}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.PURCH_DATE >= to_date(#{purchDateBegin}, 'yyyy-MM-dd')
AND T2.PURCH_DATE <= to_date(#{purchDateEnd}, 'yyyy-MM-dd')

UNION ALL SELECT #{VALID_STATUS_02} validStatus, null workflowId, null workflowStatus, T1.TOTLE_TRADE_ID busiCode, T2.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, T3.FINPROD_ID finprodId, T3.FINPROD_NAME finprodName, T1.PS ps,
CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS prinAmt, T4.PRIN_AMT winlotteryAmt, T2.PURCH_DATE purchDate,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS tradeDate, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS settleDate, T2.PURCH_MODLE purchModle, T2.PURCH_TYPE purchType, T1.TRADE_MARKET tradeMarket, T1.CCY ccy, T1.REMARK remark FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL='N') LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.TRADE_STATUS = #{VALID_STATUS_01}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND (T1.IS_CANCEL IS NULL OR T1.IS_CANCEL='N')
AND T1.PS IN
#{item}
AND ( pp.PORTFOLIO_ID IN
null) or pp.PORTFOLIO_ID in (
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
null) or pp.PARENT_PORTFOLIO_ID in (
#{item}
)
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) or pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND T2.ENTRUST_ID like CONCAT('%', CONCAT(#{entrustId}, '%'))
AND T1.FINPROD_ID like CONCAT('%', CONCAT(#{finprodId}, '%'))
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS = #{ps}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.PURCH_DATE >= to_date(#{purchDateBegin}, 'yyyy-MM-dd')
AND T2.PURCH_DATE <= to_date(#{purchDateEnd}, 'yyyy-MM-dd')

UNION ALL SELECT #{VALID_STATUS_03} validStatus, null workflowId, null workflowStatus, T1.TOTLE_TRADE_ID busiCode, T2.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, T3.FINPROD_ID finprodId, T3.FINPROD_NAME finprodName, T1.PS ps,
CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS prinAmt, nvl(T4.PRIN_AMT,T5.PRIN_AMT) winlotteryAmt, T2.PURCH_DATE purchDate,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS tradeDate, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS settleDate, T2.PURCH_MODLE purchModle, T2.PURCH_TYPE purchType, T1.TRADE_MARKET tradeMarket, T1.CCY ccy, T1.REMARK remark FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} AND T4.IS_CANCEL='N' LEFT JOIN TRD_PRODUCT_DEAL T5 ON T1.P_TRADE_ID = T5.TOTLE_TRADE_ID and T5.PS=#{PS_T05} AND T5.IS_CANCEL='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.TRADE_STATUS = #{VALID_STATUS_03}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND T1.PS IN
#{item}
AND (PP.PORTFOLIO_ID IN
null) or PP.PORTFOLIO_ID in (
#{item}
OR PP.PARENT_PORTFOLIO_ID IN
null) or PP.PARENT_PORTFOLIO_ID in (
#{item}
)
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND T2.ENTRUST_ID like CONCAT('%', CONCAT(#{entrustId}, '%'))
AND T1.FINPROD_ID like CONCAT('%', CONCAT(#{finprodId}, '%'))
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS = #{ps}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.PURCH_DATE >= to_date(#{purchDateBegin}, 'yyyy-MM-dd')
AND T2.PURCH_DATE <= to_date(#{purchDateEnd}, 'yyyy-MM-dd')

mapper.select:
SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T1.TOTLE_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
case when t1.ps=#{PS_T58} then t1.PRIN_AMT else NVL(T4.PRIN_AMT,T6.PRIN_AMT) end as winlotteryAmt, T2.DEPOSIT_AMT, nvl(t4.trade_Amt,t6.trade_Amt) supplementaryAmt,
case when t1.trade_amt < 0 then abs(t1.trade_amt) when t1.ps=#{PS_T58} then t1.trade_amt else 0 end as refundAmt, case when t1.trade_amt < 0 then t1.trade_date when t1.ps=#{PS_T58} then t1.trade_date else null end as refundDate, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05}
LEFT JOIN TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T1.TOTLE_TRADE_ID=#{tradeId}

SELECT T1.TOTLE_TRADE_ID busiCode, T2.trade_id tradeId
FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 left join wfl_trd_product_deal T2 on T1.TOTLE_TRADE_ID=T2.TOTLE_TRADE_ID and T2.PS=#{PS_T51}
T1.B_TRADE_ID = #{bTradeId}

SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.TRADE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
nvl(T4.PRIN_AMT,T6.PRIN_AMT) winlotteryAmt, T2.DEPOSIT_AMT, nvl(t4.trade_Amt,t6.trade_Amt) supplementaryAmt,
case when t1.trade_amt < 0 then abs(t1.trade_amt) else 0 end as refundAmt, case when t1.trade_amt < 0 then t1.trade_date else null end as refundDate, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05}
LEFT JOIN WFL_TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T1.TOTLE_TRADE_ID=#{tradeId}

SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.TRADE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
nvl(T5.PRIN_AMT,T6.PRIN_AMT) winlotteryAmt, T2.DEPOSIT_AMT, nvl(t4.trade_Amt,t6.trade_Amt) supplementaryAmt, t5.trade_date refundDate, t5.trade_amt refundAmt, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} LEFT JOIN WFL_TRD_PRODUCT_DEAL T5 ON T1.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID and T5.PS=#{PS_T51} LEFT JOIN WFL_TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T5.TRADE_ID=#{tradeId}

select.if:
SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =#{finprodId,jdbcType=VARCHAR}
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR (PORTFOLIO_ID || A.ACCT_NO) = #{initValue, jdbcType=VARCHAR} )
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}
AND FP.REGIST_ORG = B.REGIST_ORG

SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO
( STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}

mapper.select:
SELECT
    ACCT_NO
FROM
    PTL_CAPACCT_INFO
WHERE
    ACCT_TYPE = #{ACCT_TYPE}
  AND CCY = #{ccy}
  AND PORTFOLIO_ID = #{portfolioId}

SELECT
100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
FIN_CASH_PLAN fcp
inner join FIN_CASH_INFO fci
on fcp.CASH_ID = fci.CASH_ID
WHERE
fcp.FINPROD_ID = #{finprodId}

AND fcp.MDATE < #{settleDate}
and fci.CASH_TYPE_1 = #{cashType1}

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN PTL_SEC_ACCT PSA ON A.PORTFOLIO_ID = PSA.PORTFOLIO_ID WHERE A.INVEST_YESORNO = 'Y' and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userid}) and PSA.ACCT_NO=#{secManageAcctId,jdbcType=VARCHAR}
AND A.PORTFOLIO_ID = #{initValue}
AND ( A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

select
    AMOUNT
from PTL_CASH_POSITION
where
    (HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
  and CDATE= #{platDate,jdbcType=DATE} and CHL_FINPROD_ID=#{chlId}

select

from TRD_PRODUCT_DEAL where 1=1

    and f_trade_id=#{fTradeId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

select TRADE_AMT
from WFL_TRD_PRODUCT_DEAL
where 1=1

    and f_trade_id=#{fTradeId}


    and workflow_id != #{workflowId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

mapper.insert:
INSERT INTO TRD_PRODUCT_DEAL_ADD (TRADE_ID, PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) SELECT TRADE_ID || 'R', PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, #{updateUser}, CURRENT_TIMESTAMP FROM TRD_PRODUCT_DEAL_ADD where TRADE_ID = #{bizCode}

mapper.select:

WHERE


        TOTLE_TRADE_ID = #{totleTradeId}


        TRADE_ID = #{tradeId}

select T1.* from TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.trade_id = t2.trade_id LEFT JOIN PTL_PORTFOLIO T3 ON T3.PORTFOLIO_ID = T2.PORTFOLIO_ID WHERE T3.PARENT_PORTFOLIO_ID IS NULL
and TOTLE_TRADE_ID = #{totleTradeId}
and TRADE_ID = #{tradeId}

select count(*) from TRD_FIN_PRODUCT_DEAL_TOTAL


        and	B_TRADE_ID = #{bTradeId}


        and IS_CANCEL != #{yes}


        and TRADE_STATUS=#{tradeStatus}

select count(*) from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
where
    B_TRADE_ID = #{bTradeId}

select count(*) from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
where WORKFLOW_ID is not null

    and	(B_TRADE_ID = #{bTradeId} or P_TRADE_ID = #{bTradeId})


    and IS_CANCEL != #{yes}


    and TRADE_STATUS=#{tradeStatus}

select count(*) from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
where WORKFLOW_ID is not null

    and	 P_TRADE_ID = #{bTradeId}


    and IS_CANCEL != #{yes}


    and TRADE_STATUS=#{tradeStatus}

select ACCT_NO ACCT_NO from PTL_CAPACCT_INFO
where PORTFOLIO_ID = #{portfolioId} and CCY = #{ccy} and ACCT_TYPE = #{acctType}
and ROWNUM = 1
